// The public Guild Codex page (GET /guide), split out of pages.ts to keep
// that file under Val Town's per-file size ceiling (an oversized file makes
// vt push fail and the deploy silently stays on old code).
// Re-exported from pages.ts, so importers don't change.

import { escapeHtml } from "./utils.ts";
import { MAP_TEMPLATES } from "./maps.ts";

function renderMapTemplateList(): string {
  return Object.values(MAP_TEMPLATES)
    .map(
      (t) =>
        `<li><code>${escapeHtml(t.name)}</code> — ${escapeHtml(t.label)} (${t.width}x${t.height}): ${escapeHtml(t.description)}</li>`,
    )
    .join("");
}

export function renderGuidePage() {
  return `<style>:root{color-scheme:dark}body{max-width:1040px;background:#15120f;color:#f4eadb;font-family:Georgia,serif;line-height:1.5}a{background:transparent;color:#e6a56e;padding:0;text-decoration:underline}.actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:12px;margin-left:42px}.action-button{display:inline-flex;align-items:center;justify-content:center;background:#b97545;color:#15120f!important;border:1px solid #e6a56e;border-radius:8px;padding:14px 20px;min-width:190px;font:700 1rem ui-monospace,SFMono-Regular,monospace;text-decoration:none!important;box-shadow:0 8px 18px #0005;transition:transform .18s ease,background .18s ease}.action-button:hover{background:#e6a56e;transform:translateY(-2px)}.action-button:focus-visible{outline:3px solid #f4eadb;outline-offset:3px}h1{font-size:3rem;line-height:1.05;margin-bottom:8px;color:#f4eadb}h2{color:#e6a56e;border-bottom:1px solid #684632;padding-bottom:8px;margin-top:36px}h3{color:#f0c39e;margin-bottom:4px}p{color:#d6c6b5}.intro{font-size:1.2rem;max-width:700px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px;align-items:start}.grid.masonry{grid-auto-rows:4px;row-gap:0}.grid.masonry>*{margin-bottom:16px}.card{background:#211b16;border:1px solid #684632;border-radius:10px;padding:18px;box-shadow:0 10px 24px #0005}.cmd{display:block;background:#0e0d0c;color:#f0c39e;border-left:3px solid #b97545;padding:9px 12px;margin:8px 0;font-family:ui-monospace,SFMono-Regular,monospace;font-size:.9rem;overflow-wrap:anywhere}.note{background:#33251c;border-left:4px solid #b97545;padding:12px 16px;margin:18px 0}.muted{color:#aa9b8d;font-size:.94rem}.top{display:flex;justify-content:space-between;gap:18px;align-items:flex-start;border-bottom:1px solid #684632;padding-bottom:22px}.pill{display:inline-block;border:1px solid #b97545;border-radius:999px;padding:5px 10px;color:#e6a56e;font:600 .78rem ui-monospace,SFMono-Regular,monospace;text-transform:uppercase;letter-spacing:.08em}.switch-link{display:inline-block;margin:2px 0 6px;padding:2px 9px;border:1px solid #684632;border-radius:999px;font:600 .74rem ui-monospace,SFMono-Regular,monospace;color:#e6a56e;text-decoration:none}a.switch-link:hover{background:#33251c}.switch-link.off{color:#aa9b8d}.card{scroll-margin-top:16px}.card:target{border-color:#e6a56e;box-shadow:0 0 0 2px #e6a56e66}html{scroll-behavior:smooth}h2{scroll-margin-top:16px}.toc{background:#211b16;border:1px solid #684632;border-radius:10px;padding:16px 20px;margin:22px 0}.toc h2{margin:0 0 10px;padding:0;border:0;font-size:1.05rem;color:#e6a56e}.toc ol{margin:0;padding-left:1.2em;columns:2;column-gap:24px}.toc li{break-inside:avoid;margin:4px 0}.toc a{color:#f0c39e;text-decoration:none}.toc a:hover{text-decoration:underline}@media(max-width:600px){body{margin:20px auto;padding:16px}h1{font-size:2.35rem}.top{display:block}.actions{margin-left:0;margin-top:18px}.toc ol{columns:1}}</style><div class="top" id="top"><div><span class="pill">Guild hall · D&amp;D 5e</span><h1>GuildScribe Codex</h1><p class="intro">Welcome to the guild hall. Herein lie the rites of character, company, dice, duels, and the archives of the SRD.</p></div><div class="actions"><a class="action-button" href="/connect">Raise your banner</a><a class="action-button" href="/donate">Support the Guild</a><a class="action-button" href="/privacy">Privacy</a><a class="action-button" href="/terms">Terms</a></div></div><div class="note"><strong>Entering the hall:</strong> Grant the scribes a voice with <code>/mod GuildScribeBot</code>, then use <code>!help</code> for the welcome guide or <code>!dndbothelp</code> to browse this reference from chat.</div><nav class="toc" aria-label="Guide index"><h2>Index</h2><ol><li><a href="#parchment">Adventurer’s parchment</a></li><li><a href="#dice">Fate’s dice</a></li><li><a href="#bg3">Baldur's Gate 3</a></li><li><a href="#archives">Guild archives</a></li><li><a href="#arena">Arena, wilds &amp; the company</a></li><li><a href="#extras">Chronicle, oracle &amp; NPCs</a></li><li><a href="#gold">Gold, leaderboard &amp; giveaways</a></li><li><a href="#custom">Custom commands &amp; triggers</a></li><li><a href="#maps">Battle maps</a></li><li><a href="#onboarding">Onboarding and support</a></li></ol></nav><h2 id="parchment">Adventurer’s parchment</h2><div class="grid"><section class="card" id="card-charfun"><h3>For fun</h3><a class="switch-link" href="/dashboard/go?toggle=charfun" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: For fun</a><span class="cmd">!shmash</span><span class="cmd">!shmash @username</span><p>A purely-for-fun narrated smash using your character (race/class if you have one saved) against a target's — or a random comedic target if you leave it off. No HP, XP, or game state is touched.</p></section><section class="card" id="card-charprogress"><h3>Manage progress</h3><a class="switch-link" href="/dashboard/go?toggle=charprogress" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Manage progress</a><span class="cmd">!levelup</span><span class="cmd">!levelup +2</span><span class="cmd">!levelup -1</span><span class="cmd">!levelup @username [+/-N]</span><p>Broadcaster/moderator only: adjust your own level, or another adventurer's with <code>@username</code>, from 1 through 20. HP maximum, current HP, and proficiency are recalculated.</p><span class="cmd">!hp +5</span><span class="cmd">!hp -3</span><p>Adjust current HP within the character’s valid range.</p></section><section class="card" id="card-charsaves"><h3>Save and restore</h3><a class="switch-link" href="/dashboard/go?toggle=charsaves" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Save and restore</a><span class="cmd">!savechar</span><span class="cmd">!loadchar</span><span class="cmd">!resetchar</span><span class="cmd">!resetchar @username</span><p>Save a backup, restore the latest backup, or reset your character. Broadcaster/moderator only: <code>!resetchar @username</code> resets another player’s character.</p></section><section class="card" id="card-charcreate"><h3>Create and view</h3><a class="switch-link" href="/dashboard/go?toggle=charcreate" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Create and view</a><span class="cmd">!newchar</span><p>Start a guided chat wizard. Reply with <code>!answer &lt;choice&gt;</code> to select a race, subrace, class, and ability scores. Use <code>!cancel</code> to abandon the wizard mid-way.</p><span class="cmd">!bg3</span><p>Rolls a random Baldur's Gate 3 style race and class, then lets you assign ability scores under BG3 point-buy rules (base 8, cap 15, 27-point budget) with <code>!answer &lt;STR&gt; &lt;DEX&gt; &lt;CON&gt; &lt;INT&gt; &lt;WIS&gt; &lt;CHA&gt;</code>. Confirm with <code>!answer yes</code> to save it as your character and get a link to its page. Use <code>!cancel</code> to abandon.</p><span class="cmd">!createchar</span><p>Immediately create a level 1 character.</p><span class="cmd">!createchar @username</span><p>Broadcaster/moderator only: create a level 1 character for someone else, such as for a viewer who can't chat directly.</p><span class="cmd">!char</span><span class="cmd">!char @username</span><p>Display your current character summary, or view another player’s saved character.</p><span class="cmd">!roster</span><p>Post a link to the guild roster — a web page listing every adventurer in the channel plus every party and its members, with a search box. Open to everyone.</p><p class="muted">You keep exactly one active character and one saved backup per channel. If you already have an active character, <code>!createchar</code>, <code>!newchar</code>, and <code>!bg3</code> will warn you and ask you to confirm with <code>!answer yes</code> before overwriting it.</p></section><section class="card" id="card-streamstats"><h3>Stream stats</h3><a class="switch-link" href="/dashboard/go?toggle=streamstats" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Stream stats</a><span class="cmd">!watchtime</span><span class="cmd">!watchtime @username</span><p>How long you (or someone else) have been around this channel. The clock runs while you are in chat and the stream is live, lurkers included, and offline hours don't add up. The broadcaster must <a href="/connect">reconnect</a> once to grant the chat-list permission; until then it only counts time around your chat messages.</p><span class="cmd">!nick @username &lt;nickname&gt;</span><span class="cmd">!nick remove @username</span><span class="cmd">!nick list</span><p>Mod/broadcaster only to set or remove; <code>list</code> is open to everyone. Sets the short name battle logs use for a viewer (2-12 letters or digits), handy for all-lowercase names that would otherwise be cut to their first few letters, e.g. <code>!nick @felivore Fel</code>.</p><span class="cmd">!followage</span><span class="cmd">!followage @username</span><p>How long you (or someone else) have followed the channel. The broadcaster must <a href="/connect">reconnect</a> once to grant the follower-list permission.</p></section></div><h2 id="dice">Fate’s dice</h2><div class="grid"><section class="card" id="card-d20"><h3>D20 of Fate</h3><a class="switch-link" href="/dashboard/go?toggle=d20" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: D20 of Fate</a><span class="cmd">!d20</span><span class="cmd">!d20 @username</span><span class="cmd">!roll</span><span class="cmd">!r</span><p>Call upon the D20 of Fate. Use <code>!d20 @username</code> to roll for another adventurer.</p></section><section class="card" id="card-diceroll"><h3>Dice expressions</h3><a class="switch-link" href="/dashboard/go?toggle=diceroll" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Dice expressions</a><span class="cmd">!roll NdS[+/-M]</span><p>Roll a custom dice expression, such as <code>!roll 1d20+5</code>, <code>!roll 2d6</code>, or <code>!roll 4d8-2</code>.</p><span class="cmd">!roll @username [NdS[+/-M]]</span><p>Roll on behalf of someone else in chat, such as <code>!roll @friend</code> or <code>!roll @friend 2d6+3</code>. Anyone can do this.</p></section><section class="card" id="card-rollchecks"><h3>Saves &amp; skill checks</h3><a class="switch-link" href="/dashboard/go?toggle=rollchecks" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Saves &amp; skill checks</a><span class="cmd">!roll dex</span><span class="cmd">!roll strength</span><p>Ability saving throw. Uses your saved character's ability modifier, plus proficiency if your class is proficient in that save. Works with abbreviations (str, dex, con, int, wis, cha) or full names.</p><span class="cmd">!roll stealth</span><span class="cmd">!roll animal handling</span><p>Skill check. Uses your saved character's modifier for that skill's governing ability. Add <code>@username</code> to roll using someone else's saved character, e.g. <code>!roll @friend perception</code>.</p></section><section class="card" id="card-rollfate"><h3>Ask fate</h3><a class="switch-link" href="/dashboard/go?toggle=rollfate" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Ask fate</a><span class="cmd">!roll &lt;question&gt;?</span><p>Consult fate for a yes-or-no verdict, delivered with a random D&amp;D-flavored omen (natural 20s, Augury, a beholder's judgment, the Deck of Many Things, and more). Example: <code>!roll is enya going to die this time?</code></p></section><section class="card" id="card-rollcall"><h3>Roll call</h3><a class="switch-link" href="/dashboard/go?toggle=rollcall" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Roll call</a><span class="cmd">!rollcall</span><span class="cmd">!rollcall nat1</span><span class="cmd">!rollcall day</span><span class="cmd">!rollcall @user</span><p>Natural 1/20 leaderboard, logged automatically from every plain <code>1d20</code> roll (including ability checks/saves). Defaults to nat20 across hour/day/week; filter to <code>nat1</code>, a single window (<code>hour</code>/<code>day</code>/<code>week</code>), or <code>@user</code> for one player's own counts.</p></section></div><h2 id="bg3">Baldur's Gate 3</h2><div class="grid"><section class="card" id="card-bg3char"><h3>Roll a character (saved)</h3><a class="switch-link" href="/dashboard/go?toggle=bg3char" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Roll a character, saved</a><span class="cmd">!bg3</span><p>Rolls a random BG3-style race and class, then lets you assign ability scores under BG3 point-buy rules (base 8, cap 15, 27-point budget) with <code>!answer &lt;STR&gt; &lt;DEX&gt; &lt;CON&gt; &lt;INT&gt; &lt;WIS&gt; &lt;CHA&gt;</code>. Confirm with <code>!answer yes</code> to save it as your character and get a link to its page — see <a href="#parchment">Adventurer's parchment</a> for the rest of the character commands.</p></section><section class="card" id="card-bg3roll"><h3>Roll a character (flavor only)</h3><a class="switch-link" href="/dashboard/go?toggle=bg3roll" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Roll a character, flavor only</a><span class="cmd">!bg3roll</span><p>Rolls a full BG3-flavored character in one line: race (with subrace where BG3 has one, like High Elf or Lolth-Sworn Drow), class and subclass, background, alignment, a BG3-style 27-point point-buy ability spread weighted toward the class's primary stat, and a one-line origin hook straight off the Nautiloid.</p></section><section class="card" id="card-bg3companion"><h3>Companion &amp; origin</h3><a class="switch-link" href="/dashboard/go?toggle=bg3companion" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Companion &amp; origin</a><span class="cmd">!bg3companion</span><p>Rolls which BG3 companion you're traveling with — their role, a one-line personality blurb, and an iconic line.</p><span class="cmd">!bg3origin</span><p>Casts you as one of the six canonical BG3 Origin Characters — or the Dark Urge — for this run, with their signature hook.</p></section><section class="card" id="card-bg3loot"><h3>Loot &amp; camp</h3><a class="switch-link" href="/dashboard/go?toggle=bg3loot" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Loot &amp; camp</a><span class="cmd">!bg3loot</span><p>Rolls a random magic item drop with a BG3-style rarity tier, from Common up through Legendary.</p><span class="cmd">!bg3camp</span><p>Rolls a random camp-night vignette featuring one of the companions.</p></section><section class="card" id="card-bg3lookup"><h3>Knowledgebase</h3><a class="switch-link" href="/dashboard/go?toggle=bg3lookup" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Knowledgebase</a><span class="cmd">!bg3lookup &lt;name&gt;</span><p>Searches a hand-curated Baldur's Gate 3 knowledgebase — companions, origins, classes, races, locations, factions, deities, notable villains, and legendary items — and returns a short blurb with a link to <code>bg3.wiki</code>. Examples: <code>!bg3lookup astarion</code>, <code>!bg3lookup moonrise towers</code>.</p><span class="cmd">!bg3lookup &lt;category&gt; &lt;name&gt;</span><p>Narrow the search to one category, e.g. <code>!bg3lookup faction zhentarim</code> or <code>!bg3lookup location grymforge</code>. A bare <code>!bg3lookup</code> lists all recognized categories.</p></section></div><p class="muted"><code>!bg3roll</code>, <code>!bg3companion</code>, <code>!bg3origin</code>, <code>!bg3loot</code>, and <code>!bg3camp</code> are flavor rolls only — they print straight to chat and aren't saved, and none of them touch your <code>!createchar</code>/<code>!char</code> sheet. <code>!bg3</code> is different — it saves a real character (see the parchment section above). <code>!bg3lookup</code> is also different: it's a reference lookup against the static knowledgebase above, not a roll, so the same query always returns the same entry.</p><h2 id="archives">Guild archives</h2><p>Consult the SRD archives by name. Optional <code>+N</code> upcasts a spell or adds an item attack/damage bonus. Incomplete commands (e.g. bare <code>!rules</code>) return usage tips.</p><div class="grid"><section class="card" id="card-rules"><h3>Spells, classes &amp; rules</h3><a class="switch-link" href="/dashboard/go?toggle=rules" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Spells, classes &amp; rules</a><span class="cmd">!rules &lt;topic&gt;</span><span class="cmd">!rule &lt;topic&gt;</span><p>Summarize a rule (up to 3 messages) with a public link. Examples: <code>!rules magic</code>, <code>!rules combat</code>, <code>!rule advantage</code>.</p><span class="cmd">!spell &lt;spell&gt; [+N]</span><p>Shows level, school, casting details, range, duration, components, damage dice, damage type, save, area, classes, and higher-level scaling.</p><span class="cmd">!class &lt;class&gt; [+N]</span><p>Shows Hit Die, saving throws, and proficiencies.</p><span class="cmd">!feat &lt;feat&gt; [+N]</span><p>Shows prerequisites and the feat description.</p></section><section class="card" id="card-items"><h3>Equipment and abilities</h3><a class="switch-link" href="/dashboard/go?toggle=items" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Equipment and abilities</a><span class="cmd">!item &lt;item&gt; [+N]</span><p>Shows weapon damage, type, range, weight, cost, armor class, properties, and modifier.</p><span class="cmd">!ability &lt;ability&gt; [+N]</span><p>Shows the ability score, related skills, and description.</p></section><section class="card" id="card-races"><h3>Races</h3><a class="switch-link" href="/dashboard/go?toggle=races" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Races</a><span class="cmd">!race &lt;race&gt; [+N]</span><p>Shows ability bonuses, speed, size, languages, and racial traits.</p><span class="cmd">!subrace &lt;subrace&gt; [+N]</span><p>Shows subrace bonuses, parent race, speed, languages, and traits.</p></section></div><h2 id="arena">Arena, wilds &amp; the company</h2><p>Duels and hunts are open to any adventurer with a saved character. <strong>Auto</strong> challenges resolve when accepted. <strong>Classic</strong> modes use turn-based attack. Fights are settled by the real dice.</p><div class="grid"><section class="card" id="card-turn"><h3>Initiative tracker</h3><a class="switch-link" href="/dashboard/go?toggle=turn" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Initiative tracker</a><p>A moderator or the broadcaster starts and manages the encounter; any adventurer can roll their own initiative once it's started.</p><span class="cmd">!turn start</span><span class="cmd">!turn roll</span><span class="cmd">!turn add &lt;name&gt; &lt;initiative&gt;</span><span class="cmd">!turn show</span><span class="cmd">!turn next</span><span class="cmd">!turn prev</span><span class="cmd">!turn remove &lt;name&gt;</span><span class="cmd">!turn end</span><p><code>!turn start</code> opens the roll window; players call <code>!turn roll</code> to roll 1d20 plus their character's DEX modifier for initiative (each player rolls once per encounter). Moderators can still <code>!turn add</code> monsters, NPCs, or manual scores. The tracker stores one encounter per connected channel, sorts combatants from highest to lowest initiative, shows the active combatant with an arrow, and advances the round automatically.</p></section><section class="card" id="card-party"><h3>Parties</h3><a class="switch-link" href="/dashboard/go?toggle=party" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Parties</a><span class="cmd">!party create &lt;name&gt;</span><span class="cmd">!party join &lt;name&gt;</span><span class="cmd">!party invite @user [name]</span><span class="cmd">!party accept [name]</span><span class="cmd">!party decline [name]</span><span class="cmd">!party list [name]</span><p class="muted"><code>!party list</code> shows each of your companies with leader and members. An invite only adds someone once they <code>!party accept</code> it — the party name is optional if they only have one pending invite.</p><span class="cmd">!party leave &lt;name&gt;</span><span class="cmd">!party disband &lt;name&gt;</span><p>Create a party (you become leader and member), invite friends, and list rosters. Party name is optional on invite if you only belong to one party.</p></section><section class="card" id="card-duels"><h3>Player duels</h3><a class="switch-link" href="/dashboard/go?toggle=duels" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Player duels</a><span class="cmd">!dndduel @user</span><span class="cmd">!dndduel classic @user</span><span class="cmd">!dndduel accept | decline | attack | status | end</span><p>Challenge another adventurer to an auto or classic duel. PvP gives no XP. A pending challenge (<code>accept</code>/<code>decline</code>) expires after 5 minutes if unanswered. Any active classic duel — 1v1, party vs. party, or a hunt — auto-forfeits to the non-idle side after 10 minutes of inactivity, so a duel left mid-fight overnight won't block that channel's dueling next stream.</p><p class="muted">Want a duel with coin on the line? See <code>!rob</code> under <a href="#gold">Gold, leaderboard &amp; giveaways</a>.</p></section><section class="card" id="card-hunts"><h3>Monster hunts</h3><a class="switch-link" href="/dashboard/go?toggle=hunts" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Monster hunts</a><span class="cmd">!dndduel [monster]</span><span class="cmd">!dndduel monster [classic] [monster]</span><p>Solo <code>!dndduel</code> fights a level-scaled monster (auto); <code>!dndduel monster</code> is classic. Add a name to pick your foe, e.g. <code>!dndduel goblin</code> — a lone hero has little hope against a dragon or a beholder. One chance per solo fight for fate to stay its hand at 0 HP.</p><p><strong>Every monster you slay also drops a little coin</strong> (scaled to its level, shown in the victory message). Coin drops pause if the channel turns gold off.</p></section><section class="card" id="card-partyduels"><h3>Party duels</h3><a class="switch-link" href="/dashboard/go?toggle=partyduels" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Party duels</a><span class="cmd">!dndduel party &lt;yours&gt; &lt;theirs&gt;</span><span class="cmd">!dndduel party classic &lt;yours&gt; &lt;theirs&gt;</span><span class="cmd">!dndduel party accept | decline | attack | status | end</span><p>Pit your party against another. Each round, the first member still standing on each side swings. PvP gives no XP.</p></section><section class="card" id="card-partyhunts"><h3>Party hunts</h3><a class="switch-link" href="/dashboard/go?toggle=partyhunts" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Party hunts</a><span class="cmd">!dndduel party hunt &lt;party&gt; [monster]</span><span class="cmd">!dndduel party hunt classic &lt;party&gt; [monster]</span><span class="cmd">!dndduel party hunt attack | status | end</span><p>Party hunts fight a shared monster and award XP on victory; the hoard is split among the survivors. Name a foe, e.g. <code>!dndduel party hunt crew beholder</code> — a big enough company can take on what a lone hero can't.</p></section><section class="card" id="card-autohunt"><h3>Autohunt</h3><a class="switch-link" href="/dashboard/go?toggle=autohunt" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Autohunt</a><span class="cmd">!autohunt [20m|1h]</span><span class="cmd">!autohunt status</span><span class="cmd">!autohunt stop</span><p><strong>Autohunt</strong> sends your saved hero hunting on a timer (10 minutes to 2 hours, default 15m). About every 5 minutes they fight a level-scaled monster with the same dice, XP and loot as <code>!dndduel</code>; you get a chat report as bouts are settled and a trip total at the end. Heroes always start a fight at full HP, so a loss only costs that bout's reward.</p></section><section class="card" id="card-raid"><h3>Raid quest</h3><a class="switch-link" href="/dashboard/go?toggle=raid" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Raid quest</a><span class="cmd">!raid</span><span class="cmd">!raid go</span><span class="cmd">!raid status</span><span class="cmd">!raid cooldown [time|off]</span><span class="cmd">!raid new</span><p>When the stream goes live, one <strong>raid quest</strong> is posted: a high-level boss (CR 13+) too strong for any lone hero. <code>!raid</code> sounds the war horn and opens a muster; anyone with a saved hero types <code>!raid</code> within a minute to join the temporary party (up to 6), then it charges. The leader or a mod can <code>!raid go</code> early. The boss keeps its wounds between raids, so chat wears it down over the stream; when it falls, everyone who struck it earns its full XP and a share of a big hoard. A <strong>raid cooldown</strong> (default 10 minutes) runs between raids — mods set it with <code>!raid cooldown 5m</code> or <code>off</code> (max 2 hours), and can post a fresh quest mid-stream with <code>!raid new</code>. The quest ends with the stream.</p></section><section class="card" id="card-huntcooldown"><h3>Hunting cooldown</h3><a class="switch-link" href="/dashboard/go?toggle=huntcooldown" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Hunting cooldown</a><span class="cmd">!huntcooldown [time|off]</span><p><strong>Hunting cooldown:</strong> one cooldown covers solo hunts, party hunts and autohunt, per hero (a party hunt needs every member to be clear). Anyone can run <code>!huntcooldown</code> to see it and their own remaining wait; moderators and the broadcaster change it with e.g. <code>!huntcooldown 90s</code>, <code>!huntcooldown 5m</code> or <code>!huntcooldown off</code> (max 1 hour; default 2 minutes). PvP duels and <code>!rob</code> aren't affected.</p></section></div><h2 id="extras">Chronicle, oracle &amp; NPCs</h2><div class="grid"><section class="card" id="card-chronicle"><h3>Chronicle</h3><a class="switch-link" href="/dashboard/go?toggle=chronicle" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Chronicle</a><span class="cmd">!chronicle on</span><span class="cmd">!chronicle off</span><span class="cmd">!chronicle status</span><p><strong>Off by default.</strong> Occasionally quotes a plain chat message back with a D&amp;D-flavored reply — a random roll against qualifying messages, gated by a cooldown and a minimum amount of chat activity since the last quote. <code>status</code> is open to everyone; <code>on</code>/<code>off</code> are mod/broadcaster only.</p></section><section class="card" id="card-oracle"><h3>Oracle</h3><a class="switch-link" href="/dashboard/go?toggle=oracle" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Oracle</a><span class="cmd">!oracle &lt;question&gt;</span><p>Names a random recently-active chatter as the "answer" to your question, wrapped in D&amp;D flavor text. Example: <code>!oracle who should stream next?</code></p></section><section class="card" id="card-ads"><h3>Ad-break tracking</h3><a class="switch-link" href="/dashboard/go?toggle=ads" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Ad-break tracking</a><span class="cmd">!adcheck</span><span class="cmd">!adslogged</span><p>Mod/broadcaster only. <code>!adcheck</code> reports Twitch's real ad-schedule status for the channel (requires reconnecting to grant the <code>channel:read:ads</code> scope); <code>!adslogged</code> manually marks that an ad break just ran, as a fallback until that scope is granted.</p></section><section class="card" id="card-npc"><h3>AI-voiced NPCs</h3><a class="switch-link" href="/dashboard/go?toggle=npc" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: AI NPCs</a><span class="cmd">!npc on</span><span class="cmd">!npc off</span><span class="cmd">!npc status</span><p><strong>Off by default.</strong> Toggles this channel's invented NPC personas.</p><span class="cmd">!npc chatter on</span><span class="cmd">!npc chatter off</span><span class="cmd">!npc chatter status</span><p>Lets an NPC chime unprompted into plain chat at random — off by default, requires <code>!npc on</code> too.</p><span class="cmd">!npc list</span><span class="cmd">!npc add &lt;name&gt; &lt;personality&gt;</span><span class="cmd">!npc edit &lt;name&gt; &lt;personality&gt;</span><span class="cmd">!npc remove &lt;name&gt;</span><span class="cmd">!npc talk &lt;name&gt; &lt;message&gt;</span><p><code>list</code> and <code>talk</code> are open to everyone; <code>add</code>/<code>edit</code>/<code>remove</code> are mod/broadcaster only.</p></section></div><h2 id="gold">Gold, leaderboard &amp; giveaways</h2><div class="grid"><section class="card" id="card-chatgold"><h3>Earning gold</h3><a class="switch-link" href="/dashboard/go?toggle=chatgold" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Earning gold</a><p><strong>On by default.</strong> Viewers earn <strong>copper</strong> just by chatting while the stream is live (once per cooldown window, so spamming doesn't help), and slaying monsters in solo fights or party hunts drops a little more. Coin is tracked per channel and shown as gold, silver and copper: <strong>10 cp = 1 sp, 10 sp = 1 gp</strong>. It pays for giveaway tickets and for <code>!haggle</code>. A mod or the broadcaster can turn it all off with <code>!gold off</code>.</p><p class="muted">This switch only stops copper for chatting; monster coin drops follow the gold switch.</p></section><section class="card" id="card-goldcheck"><h3>Your purse</h3><a class="switch-link" href="/dashboard/go?toggle=goldcheck" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Your purse</a><span class="cmd">!gold</span><span class="cmd">!gold @username</span><p>Your purse and guild rank, or someone else's.</p></section><section class="card" id="card-goldgive"><h3>Gifting</h3><a class="switch-link" href="/dashboard/go?toggle=goldgive" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Gifting</a><span class="cmd">!gold give @username &lt;amount&gt;</span><p>Gift some of your coin to another adventurer. Amounts can be <code>50</code> (copper), <code>5sp</code>, <code>1gp</code>, or a mix like <code>1gp 2sp</code>.</p></section><section class="card" id="card-leaderboard"><h3>Leaderboard</h3><a class="switch-link" href="/dashboard/go?toggle=leaderboard" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Leaderboard</a><span class="cmd">!gold top [N]</span><span class="cmd">!goldboard</span><p>The richest adventurers in the channel. Shows the top 5 by default, up to 10 with <code>!gold top 10</code>.</p><p class="muted">Named <code>!gold</code> rather than <code>!points</code>/<code>!leaderboard</code> so it never collides with other chat bots' built-in commands.</p></section><section class="card" id="card-giveaways"><h3>Giveaways</h3><a class="switch-link" href="/dashboard/go?toggle=giveaways" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Giveaways</a><span class="cmd">!giveaway</span><p>See what's up for grabs, the ticket price, and how many have entered.</p><span class="cmd">!giveaway enter [tickets]</span><p>Enter a giveaway. Free giveaways are one entry each; paid ones cost coin per ticket, and more tickets means better odds (up to the giveaway's per-person cap).</p></section><section class="card" id="card-rob"><h3>Robbing</h3><a class="switch-link" href="/dashboard/go?toggle=rob" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Robbing</a><span class="cmd">!rob @username</span><p>Pick a pocket and let your characters settle it. Your saved character and theirs fight an auto-resolved duel (the same engine as <code>!dndduel</code>, but there is <strong>no accept step</strong>, and a coin flip decides who swings first). Whoever loses pays the winner a random <strong>1&ndash;9%</strong> of the loser's own coin, at least 1 cp &mdash; so a failed robbery costs <em>you</em>.</p><p class="muted">Both of you need a saved character and some coin. Only coin changes hands: nobody is hurt and no XP is earned. You can rob once every 5 minutes, and a target is left alone for 10 minutes after being targeted. Silent while gold is off; stewards can also switch it off on its own with the switch above.</p></section><section class="card" id="card-jar"><h3>Swear jar</h3><a class="switch-link" href="/dashboard/go?toggle=jar" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Swear jar</a><span class="cmd">!jar</span><p>See what's in the swear jar.</p><span class="cmd">!jar +&lt;amount&gt;</span><span class="cmd">!jar -&lt;amount&gt;</span><p>Add coin by hand (anyone), or take it out (mod/broadcaster only), e.g. <code>!jar +8</code>. Mods can also fine a viewer with <code>!jar +8 @username</code>, which moves that much of <em>their</em> gold into the jar.</p><p class="muted">Swearing in chat automatically costs <strong>2 cp per word</strong>, paid from your gold into the jar. Needs gold on.</p></section><section class="card" id="card-jarfine"><h3>Fine the streamer</h3><a class="switch-link" href="/dashboard/go?toggle=jarfine" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Fine the streamer</a><span class="cmd">!fine</span><p>Anyone can fine the streamer one swear word (2 cp from the streamer's gold into the jar). No cooldown.</p></section><section class="card" id="card-jarwords"><h3>Jar vocabulary</h3><a class="switch-link" href="/dashboard/go?toggle=jarwords" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Jar vocabulary</a><span class="cmd">!jar words</span><span class="cmd">!jar forget &lt;word&gt;</span><p>The jar learns new swear words from your own chat (unknown words used next to swearing by several different chatters, and rarely otherwise). Mods can list what it has learned or veto a word.</p></section><section class="card" id="card-jargiveaway"><h3>Jar giveaway</h3><a class="switch-link" href="/dashboard/go?toggle=jargiveaway" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Jar giveaway</a><span class="cmd">!jar giveaway</span><p>Mod/broadcaster only: gives the whole jar to a random chatter from the past week and empties it. Once every 7 days. No cooldown.</p></section><section class="card" id="card-boonsetup"><h3>Link channel-point rewards</h3><a class="switch-link" href="/dashboard/go?toggle=boonsetup" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Link channel-point rewards</a><span class="cmd">!boon add shield &lt;minutes&gt; &lt;reward title&gt;</span><span class="cmd">!boon add lockout &lt;minutes&gt; &lt;reward title&gt;</span><span class="cmd">!boon remove &lt;reward title&gt;</span><span class="cmd">!boon clear @username</span><p>Mod/broadcaster only. Link a Twitch channel-point reward (exact title) to a <strong>robbery shield</strong> (the redeemer can't be <code>!rob</code>bed) or a <strong>lockout</strong> (the redeemer hexes another viewer out of a feature). For lockouts, make the reward require viewer input and have redeemers type <code>&lt;user&gt; &lt;feature&gt;</code>, e.g. <code>bob rob</code>. Features: rob, haggle, duel, autohunt, dice, gold.</p></section><section class="card" id="card-boonstatus"><h3>Reward status</h3><a class="switch-link" href="/dashboard/go?toggle=boonstatus" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Reward status</a><span class="cmd">!boon list</span><span class="cmd">!boon status [@username]</span><p>Open to everyone: see which rewards are linked and what shields or hexes are active. The broadcaster must <a href="/connect">reconnect</a> once to grant the redemptions permission.</p></section><section class="card" id="card-points"><h3>Running it (mod/broadcaster)</h3><a class="switch-link" href="/dashboard/go?toggle=points" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Gold, leaderboard &amp; giveaways</a><span class="cmd">!gold on</span><span class="cmd">!gold off</span><span class="cmd">!gold status</span><p>Turn the whole system on or off for the channel. Balances are kept while it's off. <code>status</code> is open to everyone. Also available as a switch on the <code>!dashboard</code> page.</p><span class="cmd">!gold add|remove|set @username &lt;amount&gt;</span><p>Adjust a balance by hand, e.g. <code>!gold add @friend 2gp</code>.</p><span class="cmd">!giveaway start [cost=&lt;amount&gt;] [max=N] &lt;prize&gt;</span><p>Open a giveaway, e.g. <code>!giveaway start cost=5sp max=5 Steam key</code> (no spaces inside the cost). Leave off <code>cost</code> for a free one.</p><span class="cmd">!giveaway draw</span><span class="cmd">!giveaway reroll</span><span class="cmd">!giveaway cancel</span><p><code>draw</code> picks a winner (weighted by tickets) and closes entries, <code>reroll</code> draws again if the winner doesn't respond, and <code>cancel</code> calls it off and refunds every ticket.</p></section></div><h2 id="custom">Custom commands &amp; triggers</h2><p>Broadcasters and moderators can add their own commands and passive keyword auto-responses right from chat — no code required. These share the <code>!dndbot</code> word used for bot settings below, but different subcommands, so nothing collides. <code>list</code> is open to everyone; the rest are mod/broadcaster only.</p><div class="grid"><section class="card" id="card-customcmds"><h3>Custom commands</h3><a class="switch-link" href="/dashboard/go?toggle=customcmds" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Custom commands</a><span class="cmd">!dndbot add &lt;name&gt; &lt;response&gt;</span><span class="cmd">!dndbot edit &lt;name&gt; &lt;response&gt;</span><span class="cmd">!dndbot remove &lt;name&gt;</span><span class="cmd">!dndbot cooldown &lt;name&gt; &lt;seconds&gt;</span><span class="cmd">!dndbot list</span><p>Creates <code>!&lt;name&gt;</code> as a new chat command. Built-in command names can't be used or overridden.</p></section><section class="card" id="card-triggers"><h3>Chat triggers</h3><a class="switch-link" href="/dashboard/go?toggle=triggers" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Chat triggers</a><span class="cmd">!trigger add &lt;keyword&gt; &lt;response&gt;</span><span class="cmd">!trigger remove &lt;keyword&gt;</span><span class="cmd">!trigger cooldown &lt;keyword&gt; &lt;seconds&gt;</span><span class="cmd">!trigger list</span><p>Fires the response automatically whenever <code>&lt;keyword&gt;</code> appears in chat (no <code>!</code> needed to trigger it) — wrap multi-word keywords in quotes, e.g. <code>!trigger add "good luck" May the dice favor you!</code></p></section></div><p class="muted">Each channel has a cap on the number of custom commands/triggers and a default cooldown to prevent spam.</p><h3 id="placeholders">Response placeholders</h3><p class="muted">Drop any of these into a command or trigger response.</p><div class="grid"><section class="card"><h3>Who &amp; what</h3><span class="cmd">{user}</span><span class="cmd">{sender}</span><p>Display name of whoever triggered it.</p><span class="cmd">{target}</span><p>First @mentioned user in a command's arguments (commands only; falls back to {user}).</p><span class="cmd">{touser}</span><p>First word of the arguments with a leading @ stripped (falls back to {user}).</p><span class="cmd">{args}</span><p>Everything typed after the command, or the whole message for a trigger.</p><span class="cmd">{count}</span><p>How many times this command/trigger has now fired.</p></section><section class="card"><h3>Randomness &amp; math</h3><span class="cmd">{random:a|b|c}</span><p>Picks one option at random (max 5 per response).</p><span class="cmd">{randnum:MIN-MAX}</span><p>Random whole number in the given range — negatives allowed, e.g. {randnum:-5-10}.</p><span class="cmd">{d4} {d6} {d8} {d10} {d12} {d20} {d100}</span><p>Rolls that die and inserts the result.</p><span class="cmd">{repeat:N|text}</span><p>Repeats text back-to-back N times (up to 10).</p><span class="cmd">{math:expr}</span><p>Evaluates a numeric expression, e.g. {math:(3+4)*2}.</p></section><section class="card"><h3>Channel info</h3><span class="cmd">{channel}</span><p>The broadcaster's display name.</p><span class="cmd">{time}</span><span class="cmd">{date}</span><p>Current UTC time (HH:MM) and date (YYYY-MM-DD).</p><span class="cmd">{game}</span><span class="cmd">{title}</span><span class="cmd">{status}</span><span class="cmd">{uptime}</span><p>Live channel info — category, stream title, live/offline status, and how long the stream has been live.</p><span class="cmd">{twitchemotes}</span><span class="cmd">{7tvemotes}</span><span class="cmd">{bttvemotes}</span><span class="cmd">{ffzemotes}</span><p>A random emote from that provider's set for this channel.</p></section></div><h2 id="maps">Battle maps</h2><div class="grid"><section class="card" id="card-maps"><h3>Create &amp; view</h3><a class="switch-link" href="/dashboard/go?toggle=maps" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Create &amp; view maps</a><span class="cmd">!map create &lt;name&gt; [WxH] [template]</span><p>Mod/broadcaster only. Makes a new grid map (default 10x8, up to 20x20), starting as all grass — or stamped with a template's terrain if you name one, e.g. <code>!map create tav1 tavern</code> or <code>!map create tav1 14x10 tavern</code>.</p><span class="cmd">!map list</span><span class="cmd">!map view &lt;name&gt;</span><p>List every map in the channel, or post a link to one — the map page is a live, auto-refreshing visual grid.</p><span class="cmd">!map delete &lt;name&gt;</span><span class="cmd">!map remove &lt;name&gt;</span><p>Mod/broadcaster only. Deletes the map along with its terrain and every character token on it — this can't be undone.</p></section><section class="card" id="card-maptemplates"><h3>Templates</h3><a class="switch-link" href="/dashboard/go?toggle=maptemplates" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Map templates</a><span class="cmd">!map templates</span><p>Lists every ready-made layout you can stamp onto a new map with <code>!map create &lt;name&gt; [WxH] &lt;template&gt;</code>. A template sets its own default size (overridable) and pre-paints walls, doors, hazards, and features — a starting point you can still touch up with <code>!map paint</code>/<code>!map fill</code> afterward.</p><ul>${renderMapTemplateList()}</ul></section><section class="card" id="card-mapterrain"><h3>Edit the terrain</h3><a class="switch-link" href="/dashboard/go?toggle=mapterrain" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Edit the terrain</a><span class="cmd">!map terrains</span><p>Lists every terrain type (grass, forest, water, sand, mountain, road, floor, wall, door, trap, lava, void) — some, like water/wall/mountain/lava/void, block tokens from standing there.</p><span class="cmd">!map fill &lt;name&gt; &lt;terrain&gt;</span><p>Mod/broadcaster only. Resets the whole grid to one terrain.</p><span class="cmd">!map paint &lt;name&gt; &lt;x&gt; &lt;y&gt; &lt;terrain&gt;</span><p>Mod/broadcaster only. Sets a single cell, e.g. <code>!map paint dungeon1 4 2 wall</code>. Coordinates start at (1,1) in the top-left.</p></section><section class="card" id="card-maptokens"><h3>Place &amp; move characters</h3><a class="switch-link" href="/dashboard/go?toggle=maptokens" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Place &amp; move characters</a><span class="cmd">!map addchar &lt;name&gt; [x y]</span><p>Puts your saved character on the map, at the coordinates you give or the first free cell otherwise.</p><span class="cmd">!map addchar &lt;name&gt; @user [x y]</span><p>Mod/broadcaster only: place someone else's character.</p><span class="cmd">!map move &lt;name&gt; &lt;x&gt; &lt;y&gt;</span><span class="cmd">!map move &lt;name&gt; @user &lt;x&gt; &lt;y&gt;</span><p>Move a token; the second form (moving someone else) is mod/broadcaster only.</p><span class="cmd">!map removechar &lt;name&gt; [@user]</span><p>Take a character off the map.</p></section></div><p class="muted">Map creation, terrain painting, and moving <em>someone else's</em> token are restricted to the broadcaster/moderators, the same as the rest of the guild's shared state; everyone can place and move their own character.</p><h2 id="onboarding">Onboarding and support</h2><div class="grid"><section class="card"><h3>In chat</h3><span class="switch-link off">Always on — no switch</span><span class="cmd">!help</span><p>Welcome to the guild hall and a path to begin your legend.</p><span class="cmd">!guide</span><span class="cmd">!link</span><p>Post the Guild Codex URL in chat.</p><span class="cmd">!dndbothelp</span><p>List codex chapters.</p><p>Expand one of: <code>!dndbothelp dice</code>, <code>!dndbothelp character</code>, <code>!dndbothelp party</code>, <code>!dndbothelp combat</code>, <code>!dndbothelp lookup</code>, <code>!dndbothelp gold</code>, <code>!dndbothelp settings</code>.</p></section><section class="card"><h3>Connect and support</h3><p>Use the <a href="/">onboarding page</a> to connect a Twitch channel. After connecting, run <code>/mod GuildScribeBot</code> in that channel.</p><p>Already connected? <a href="/connect">Reconnect your channel</a> any time to grant newly requested permissions as GuildScribe gains features — safe to run repeatedly, and won't duplicate or lose your existing data.</p><p>Support the project through the <a href="/donate">donations page</a>.</p><p>Moderators can review recent activity for their channel with <code>!logs</code> in chat.</p></section><section class="card" id="card-bot"><h3>Guild stewards (mod/broadcaster)</h3><a class="switch-link" href="/dashboard/go?toggle=bot" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Entire bot</a><span class="cmd">!dndbot on</span><span class="cmd">!dndbot off</span><span class="cmd">!dndbot status</span><span class="cmd">!dndbot leave</span><span class="cmd">!dndbot leave purge</span><p>Enable/disable the bot. The broadcaster can disconnect with <code>!dndbot leave</code>; add <code>purge</code> to delete channel data.</p><span class="cmd">!gold on</span><span class="cmd">!gold off</span><span class="cmd">!gold status</span><p><strong>On by default.</strong> Toggles gold, the gold leaderboard, giveaways, and paid haggling (see <a href="#gold">Gold, leaderboard &amp; giveaways</a>). Balances are kept while it is off. <code>status</code> is open to everyone; <code>on</code>/<code>off</code> are mod/broadcaster only.</p></section><section class="card" id="card-market"><h3>Market and peddler</h3><a class="switch-link" href="/dashboard/go?toggle=market" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Open-stall merchant</a><span class="cmd">!market on</span><span class="cmd">!market off</span><span class="cmd">!market status</span><p><strong>Off by default.</strong> Toggles a threadbare open-stall merchant who drops by the channel every so often (interval randomized per channel) with a one-line D&amp;D-flavored sales pitch for some cheap, secondhand good. Purely flavor — no coin, inventory, or character state involved. <code>status</code> is open to everyone; <code>on</code>/<code>off</code> are mod/broadcaster only.</p><p>Viewers can see and bargain over the current listing with <a href="#card-stall"><code>!stall</code></a> and <a href="#card-haggle"><code>!haggle</code></a>.</p></section><section class="card" id="card-stall"><h3>Peddler's stall</h3><a class="switch-link" href="/dashboard/go?toggle=market" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Open-stall merchant</a><span class=\"cmd\">!stall</span><p>Open to everyone. Shows the item the peddler is currently selling, its price, and how many haggle attempts you have left on it (three per viewer per listing). Read-only — it never spends an attempt or any coin. Requires an active <code>!market</code> listing.</p></section><section class="card" id="card-haggle"><h3>Haggling</h3><a class="switch-link" href="/dashboard/go?toggle=market" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Open-stall merchant</a><span class=\"cmd\">!haggle &lt;pitch&gt;</span><p>Open to everyone. Bargains with whichever peddler last set up shop, over whatever they're currently selling — an AI-voiced, sassy, in-character verdict (a discount, a refusal, a smaller counter-offer, or a silly trade demand). Requires an active <code>!market</code> listing; three attempts per viewer per listing. <strong>The prices are real coin</strong> (earned by chatting — see <a href="#gold">Gold, leaderboard &amp; giveaways</a>). Name your offer in the pitch, e.g. <code>!haggle come on, five copper is robbery</code>; if the peddler agrees to a price, you pay exactly that on the spot (never more than listed, never less than you offered). A refusal costs nothing. Free banter if the channel has turned gold off.</p></section><section class="card" id="card-autoban"><h3>Chat moderation</h3><a class="switch-link" href="/dashboard/go?toggle=autoban" title="Mods: jump to this card's on/off switch on your channel dashboard">⚙ Dashboard switch: Auto-ban</a><span class="cmd">!autoban on</span><span class="cmd">!autoban off</span><span class="cmd">!autoban status</span><p><strong>Off by default.</strong> Permanently bans anyone who is not a moderator or the broadcaster the moment they say <code>ai viewers</code> in chat (the fake-viewer-service spam), then posts a short D&amp;D-flavored line to let the channel know. <code>on</code>/<code>off</code> are mod/broadcaster; <code>status</code> is open to everyone. Bans run on the broadcaster's own connection, so the broadcaster must <a href="/connect">reconnect</a> once to grant the ban permission.</p></section></div><p><a href="/privacy">Privacy Policy</a> · <a href="/terms">Terms of Service</a> · <a href="/donate">Support</a> · <a href="#top">Back to top</a></p><p class="muted">GuildScribe provides reference and gameplay utilities. Always verify rules, character choices, and wallet details before acting.</p><script>(function(){var ROW=4,GAP=16,grids=[].slice.call(document.querySelectorAll(".grid"));function lay(){grids.forEach(function(g){[].forEach.call(g.children,function(c){c.style.gridRowEnd="span "+Math.ceil((c.getBoundingClientRect().height+GAP)/ROW)})})}grids.forEach(function(g){g.classList.add("masonry")});lay();if(window.ResizeObserver){var ro=new ResizeObserver(function(){lay()});grids.forEach(function(g){[].forEach.call(g.children,function(c){ro.observe(c)})})}else window.addEventListener("resize",lay);if(document.fonts&&document.fonts.ready)document.fonts.ready.then(lay);})();</script>`;
}
